"use client";

import type { ComponentType } from "react";
import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface EcosystemConstellationProps {
  /** Label rendered inside the central hub node. */
  centerLabel?: string;
  /** Headline rendered under the constellation. Empty string hides it. */
  headline?: string;
  /** Number of orbiting integration satellites (clamped to 3..6). */
  satelliteCount?: number;
  /** Color of the data pulse travelling from the hub to each satellite. */
  accentColor?: string;
  /** Light (default) or dark surface preset. */
  theme?: "light" | "dark";
  /** Global playback multiplier. */
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

const THEMES = {
  light: {
    surface: "#FFFFFF",
    border: "#E4E7EC",
    text: "#101828",
    muted: "#667085",
    nodeShadow:
      "0 1px 2px rgba(16, 24, 40, 0.06), 0 4px 12px rgba(16, 24, 40, 0.04)",
  },
  dark: {
    surface: "#141417",
    border: "#26272B",
    text: "#FAFAFA",
    muted: "#A1A1AA",
    nodeShadow: "0 1px 2px rgba(0, 0, 0, 0.5), 0 4px 12px rgba(0, 0, 0, 0.35)",
  },
} as const;

// ---------------------------------------------------------------------------
// Pure helpers (exported for tests)
// ---------------------------------------------------------------------------

/** Which satellite the data pulse is currently firing toward. */
export function activeSatelliteIndex(
  frame: number,
  windowFrames: number,
  count: number,
): number {
  if (count <= 0 || windowFrames <= 0) {
    return -1;
  }
  return Math.floor(Math.max(0, frame) / windowFrames) % count;
}

/** Angle (radians) of satellite `i` of `count`, drifting slowly with frame. */
export function satelliteAngle(
  i: number,
  count: number,
  frame: number,
  driftSpeed: number,
): number {
  return -Math.PI / 2 + (i / count) * Math.PI * 2 + frame * driftSpeed;
}

/** Point on the segment hub -> satellite at progress t (clamped to 0..1). */
export function pulsePoint(
  cx: number,
  cy: number,
  sx: number,
  sy: number,
  t: number,
): { x: number; y: number } {
  const p = Math.min(1, Math.max(0, t));
  return { x: cx + (sx - cx) * p, y: cy + (sy - cy) * p };
}

// ---------------------------------------------------------------------------
// Generic integration glyphs — primitive stroke icons, no real brands.
// ---------------------------------------------------------------------------

interface GlyphProps {
  color: string;
}

function ChatGlyph({ color }: GlyphProps) {
  return (
    <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden="true">
      <path
        d="M4 6.5A2.5 2.5 0 0 1 6.5 4h11A2.5 2.5 0 0 1 20 6.5v7a2.5 2.5 0 0 1-2.5 2.5H9.5L5 19.5V16a2.5 2.5 0 0 1-1-2v-7z"
        fill="none"
        stroke={color}
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function GitGlyph({ color }: GlyphProps) {
  return (
    <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden="true">
      <g
        fill="none"
        stroke={color}
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <circle cx="6" cy="5" r="2.4" />
        <circle cx="6" cy="19" r="2.4" />
        <circle cx="18" cy="7" r="2.4" />
        <path d="M6 7.4v9.2" />
        <path d="M18 9.4c0 3.2-2.6 5-6 5.4-2.4.3-4.4 1-5.2 2.4" />
      </g>
    </svg>
  );
}

function MailGlyph({ color }: GlyphProps) {
  return (
    <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden="true">
      <g
        fill="none"
        stroke={color}
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <rect x="3" y="5.5" width="18" height="13" rx="2.2" />
        <path d="m4.5 8 7.5 5 7.5-5" />
      </g>
    </svg>
  );
}

function SheetGlyph({ color }: GlyphProps) {
  return (
    <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden="true">
      <g
        fill="none"
        stroke={color}
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <rect x="3.5" y="4" width="17" height="16" rx="2.2" />
        <path d="M3.5 10h17" />
        <path d="M9.5 10v10" />
        <path d="M15 10v10" />
      </g>
    </svg>
  );
}

function CalendarGlyph({ color }: GlyphProps) {
  return (
    <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden="true">
      <g
        fill="none"
        stroke={color}
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <rect x="3.5" y="5.5" width="17" height="15" rx="2.2" />
        <path d="M3.5 10.5h17" />
        <path d="M8.5 3v4" />
        <path d="M15.5 3v4" />
      </g>
    </svg>
  );
}

function WebhookGlyph({ color }: GlyphProps) {
  return (
    <svg viewBox="0 0 24 24" width={24} height={24} aria-hidden="true">
      <g
        fill="none"
        stroke={color}
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M18 16.98h-5.99c-1.1 0-1.95.94-2.48 1.9A4 4 0 0 1 2 17c.01-.7.2-1.4.57-2" />
        <path d="m6 17 3.13-5.78c.53-.97.1-2.18-.5-3.1a4 4 0 1 1 6.89-4.06" />
        <path d="m12 6 3.13 5.73C15.66 12.7 16.9 13 18 13a4 4 0 0 1 0 8" />
      </g>
    </svg>
  );
}

const SATELLITE_GLYPHS: ComponentType<GlyphProps>[] = [
  ChatGlyph,
  GitGlyph,
  MailGlyph,
  SheetGlyph,
  CalendarGlyph,
  WebhookGlyph,
];

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const PULSE_WINDOW = 42; // frames per satellite pulse cycle

export function EcosystemConstellation({
  centerLabel = "Acme",
  headline = "One API, every integration",
  satelliteCount = 6,
  accentColor = "#266DF0",
  theme = "light",
  speed = 1,
  className,
}: EcosystemConstellationProps) {
  const frame = useCurrentFrame() * speed;
  const palette = THEMES[theme] ?? THEMES.light;

  const count = Math.max(
    3,
    Math.min(SATELLITE_GLYPHS.length, Math.floor(satelliteCount)),
  );

  // Geometry (composition-space, 1280x720 viewBox)
  const cx = 640;
  const cy = 328;
  const baseRadiusX = 224;
  const baseRadiusY = 148;

  // Slow center breathing (very subtle — chrome, not bounce)
  const breathe = (Math.sin(frame / 26) + 1) / 2;

  // Data pulse scheduling
  const activeIdx = activeSatelliteIndex(frame, PULSE_WINDOW, count);
  const localFrame = Math.max(0, frame) % PULSE_WINDOW;
  const pulseTravel = interpolate(localFrame, [6, 32], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });
  const pulseOpacity = interpolate(localFrame, [4, 10, 30, 38], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Satellite acknowledgement as the pulse arrives
  const arrivalGlow = interpolate(localFrame, [28, 33, 42], [0, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const satellites = Array.from({ length: count }).map((_, i) => {
    // Staggered assembly: satellites ease in from far outside the frame.
    const assemble = interpolate(frame - i * 5, [0, 46], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    });
    const radiusFactor = interpolate(assemble, [0, 1], [5, 1]);

    // Slight elliptical variation per orbit, drifting slowly.
    const orbitOffset = i * 16;
    const rX = baseRadiusX + orbitOffset;
    const rY = baseRadiusY + orbitOffset * 0.6;
    const angle = satelliteAngle(i, count, frame, 0.0045 - i * 0.0004);

    const x = cx + Math.cos(angle) * rX * radiusFactor;
    const y = cy + Math.sin(angle) * rY * radiusFactor;

    const isActive = i === activeIdx;
    return {
      x,
      y,
      Glyph: SATELLITE_GLYPHS[i % SATELLITE_GLYPHS.length],
      isActive,
      glow: isActive ? arrivalGlow : 0,
      visible: assemble > 0.02,
      opacity: interpolate(assemble, [0, 0.25], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }),
    };
  });

  const active = satellites[Math.max(0, activeIdx)] ?? satellites[0];
  const pulse = pulsePoint(cx, cy, active.x, active.y, pulseTravel);
  const pulseTrail = pulsePoint(cx, cy, active.x, active.y, pulseTravel - 0.16);

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        background: "transparent",
        fontFamily: FONT_FAMILY,
      }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox="0 0 1280 720"
        style={{ position: "absolute", inset: 0 }}
      >
        {/* Hairline orbit guides */}
        <ellipse
          cx={cx}
          cy={cy}
          rx={baseRadiusX}
          ry={baseRadiusY}
          fill="none"
          stroke={palette.border}
          strokeWidth={1}
          strokeDasharray="2 6"
          opacity={0.7}
        />
        <ellipse
          cx={cx}
          cy={cy}
          rx={baseRadiusX + 80}
          ry={baseRadiusY + 48}
          fill="none"
          stroke={palette.border}
          strokeWidth={1}
          strokeDasharray="2 6"
          opacity={0.45}
        />

        {/* Hairline connection lines */}
        {satellites.map((s, i) => (
          <line
            // biome-ignore lint/suspicious/noArrayIndexKey: satellites are positional and never reorder
            key={`line-${i}`}
            x1={cx}
            y1={cy}
            x2={s.x}
            y2={s.y}
            stroke={palette.border}
            strokeWidth={1}
            strokeLinecap="round"
            opacity={s.visible ? 0.9 : 0}
          />
        ))}

        {/* Accent pulse travelling outward along the active line */}
        {active.visible ? (
          <g opacity={pulseOpacity}>
            <line
              x1={pulseTrail.x}
              y1={pulseTrail.y}
              x2={pulse.x}
              y2={pulse.y}
              stroke={accentColor}
              strokeWidth={2}
              strokeLinecap="round"
              opacity={0.55}
            />
            <circle cx={pulse.x} cy={pulse.y} r={4} fill={accentColor} />
            <circle
              cx={pulse.x}
              cy={pulse.y}
              r={9}
              fill={accentColor}
              opacity={0.14}
            />
          </g>
        ) : null}
      </svg>

      {/* Center hub node */}
      <div
        style={{
          position: "absolute",
          left: cx,
          top: cy,
          width: 128,
          height: 96,
          marginLeft: -64,
          marginTop: -48,
          borderRadius: 10,
          background: palette.surface,
          border: `1px solid ${palette.border}`,
          boxShadow: palette.nodeShadow,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          scale: String(
            interpolate(frame, [0, 18], [0.92, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            }) *
              (1 + breathe * 0.015),
          ),
          opacity: interpolate(frame, [0, 12], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
        }}
      >
        <span
          style={{
            fontSize: 26,
            fontWeight: 600,
            letterSpacing: "-0.02em",
            color: palette.text,
          }}
        >
          {centerLabel}
        </span>
      </div>

      {/* Satellite coins */}
      {satellites.map((s, i) => {
        const Glyph = s.Glyph;
        return (
          <div
            // biome-ignore lint/suspicious/noArrayIndexKey: satellites are positional and never reorder
            key={`sat-${i}`}
            style={{
              position: "absolute",
              left: s.x,
              top: s.y,
              width: 60,
              height: 60,
              marginLeft: -30,
              marginTop: -30,
              borderRadius: 30,
              background: palette.surface,
              border: `1px solid ${palette.border}`,
              boxShadow:
                s.glow > 0.01
                  ? `${palette.nodeShadow}, 0 0 0 ${(s.glow * 4).toFixed(2)}px ${accentColor}26`
                  : palette.nodeShadow,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              scale: String(1 + s.glow * 0.05),
              opacity: s.opacity,
              willChange: "transform",
            }}
          >
            <Glyph color={s.glow > 0.5 ? accentColor : palette.muted} />
          </div>
        );
      })}

      {/* Headline */}
      {headline ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: 596,
            textAlign: "center",
            fontSize: 34,
            fontWeight: 600,
            letterSpacing: "-0.02em",
            color: palette.text,
            opacity: interpolate(frame, [20, 44], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }),
            translate: interpolate(frame, [20, 44], ["0px 10px", "0px 0px"], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            }),
          }}
        >
          {headline}
        </div>
      ) : null}
    </div>
  );
}
